package com.carrot.transport;
import android.graphics.Rect;import android.os.SystemClock;import android.view.*;import java.lang.reflect.*;import java.util.*;import java.util.regex.*;
/** Read-only semantics bounds for Naver 6.11.2.2's Compose navigation controls. */
public final class ComposeRegions {
 public static final class Region {public final Rect bounds;public final String description;public final boolean clickable;Region(Rect b,String d){bounds=b;description=d;clickable=d.contains("OnClick");}}
 static View cachedRoot;static long cachedAt;static List<Region> cached=Collections.emptyList();static final Map<String,Method> methods=new HashMap<>();
 static Object call(Object o,String name)throws Exception{String key=o.getClass().getName()+"#"+name;Method m=methods.get(key);if(m==null){m=o.getClass().getMethod(name);m.setAccessible(true);methods.put(key,m);}return m.invoke(o);}
 static Rect bounds(Object node)throws Exception{String s=String.valueOf(call(node,"m"));Matcher match=Pattern.compile("-?\\d+(?:\\.\\d+)?").matcher(s);float[] v=new float[4];for(int i=0;i<4;i++){if(!match.find())return null;v[i]=Float.parseFloat(match.group());}return new Rect((int)Math.floor(v[0]),(int)Math.floor(v[1]),(int)Math.ceil(v[2]),(int)Math.ceil(v[3]));}
 static void node(Object node,View compose,List<Region> result,Set<Integer> seen,int[] origin)throws Exception{int id=((Number)call(node,"s")).intValue();if(!seen.add(id)||seen.size()>600)return;String config=String.valueOf(call(node,"r"));Rect rect=bounds(node);if(rect!=null&&!rect.isEmpty()&&!config.endsWith("{}")){int[] at=new int[2];compose.getLocationOnScreen(at);rect.offset(at[0]-origin[0],at[1]-origin[1]);result.add(new Region(rect,config));}for(String children:new String[]{"o","B"}){Object list=call(node,children);if(list instanceof List)for(Object child:(List<?>)list)node(child,compose,result,seen,origin);}}
 static void walk(View v,List<Region> result,int[] origin){if(!v.isShown())return;if(v.getClass().getName().equals("androidx.compose.ui.platform.AndroidComposeView"))try{Object owner=call(v,"getSemanticsOwner");node(call(owner,"d"),v,result,new HashSet<>(),origin);}catch(Exception ignored){}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)walk(((ViewGroup)v).getChildAt(i),result,origin);}
 public static List<Region> get(View root){if(!root.getContext().getPackageName().equals("com.nhn.android.nmap"))return Collections.emptyList();long now=SystemClock.elapsedRealtime();if(cachedRoot==root&&now-cachedAt<700)return cached;List<Region> result=new ArrayList<>();int[] origin=new int[2];root.getLocationOnScreen(origin);walk(root,result,origin);cachedRoot=root;cachedAt=now;cached=result;return result;}
 public static boolean search(View root){for(Region r:get(root))if(r.description.contains("EditableText")&&r.bounds.width()>0)return true;return false;}
 public static Rect signal(View root){Rect found=null;for(Region r:get(root)){String d=r.description.toLowerCase(Locale.ROOT);boolean signal=(d.contains("trafficlight")||d.contains("trafficsignal")||d.contains("신호등")||d.contains("신호 정보")||d.matches("(?s).*\\d+\\s*초.*"));if(!signal||d.contains("카메라")||d.contains("단속")||r.bounds.width()>root.getWidth()*.75||r.bounds.height()>root.getHeight()*.25)continue;if(found==null)found=new Rect(r.bounds);else found.union(r.bounds);}return found;}
 private ComposeRegions(){}
}
